//! The exobiology catalogue (`data/catalog/exobiology.json`, generated by
//! `scripts/gen-exobiology.py`; sources in NOTICE.md): every genus with its journal symbol and
//! colony range, and every species with its base value and, for the Odyssey genera, the
//! conditions it grows in.

use serde::{Deserialize, Serialize};
use std::sync::OnceLock;

#[derive(Debug, Deserialize)]
struct File {
    genera: Vec<Genus>,
}

/// A genus: "Stratum", "Bacterium", ...
#[derive(Debug, Clone, Deserialize)]
pub struct Genus {
    pub name: String,
    /// The journal symbol's middle part(s): `Stratum` in `$Codex_Ent_Stratum_Genus_Name;`, also
    /// what Spansh lists as a body's `genuses`.
    pub codex: Vec<String>,
    /// The least distance between two samples of the genus, in metres.
    pub colony_range_m: u32,
    pub species: Vec<Species>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Species {
    /// As the game writes it (`Species_Localised`): "Stratum Tectonicas".
    pub name: String,
    /// The journal's `Species` symbol, lower case (`$codex_ent_stratum_07_name;`), where known.
    #[serde(default)]
    pub symbol: Option<String>,
    /// Vista Genomics base value in credits, before the first-logged bonus.
    pub value: i64,
    /// Any one of these is enough (none: no prediction, the Horizons-era genera).
    #[serde(default)]
    pub rules: Vec<Conditions>,
}

/// Where a species grows. Every field present must match; a missing field doesn't constrain.
#[derive(Debug, Clone, Default, Deserialize, Serialize, PartialEq)]
pub struct Conditions {
    /// Journal `AtmosphereType`s: `CarbonDioxide`, `SulphurDioxide`, ...
    pub atmosphere: Option<Vec<String>>,
    /// Journal `PlanetClass`es: "Rocky body", "High metal content body", ...
    pub body_types: Option<Vec<String>>,
    /// Star classes of the nearest parent star, normalised by [`star_class`].
    pub star_types: Option<Vec<String>>,
    pub min_gravity_g: Option<f64>,
    pub max_gravity_g: Option<f64>,
    pub min_temp_k: Option<f64>,
    pub max_temp_k: Option<f64>,
    pub min_pressure_atm: Option<f64>,
    pub max_pressure_atm: Option<f64>,
    pub volcanism: Option<Volcanism>,
    /// Set when the rule leaves out something that matters (region, nebula, ...); such a rule
    /// is only used for a body known to have biology.
    pub unmodeled: Option<String>,
}

/// `"none"`, `"any"`, or keywords one of which the journal's `Volcanism` text must contain.
#[derive(Debug, Clone, Deserialize, Serialize, PartialEq)]
#[serde(untagged)]
pub enum Volcanism {
    Word(String),
    Keywords(Vec<String>),
}

fn file() -> &'static File {
    static F: OnceLock<File> = OnceLock::new();
    F.get_or_init(|| {
        serde_json::from_str(include_str!("../../../data/catalog/exobiology.json")).expect("exobiology.json")
    })
}

/// Every genus.
pub fn genera() -> &'static [Genus] {
    &file().genera
}

/// The genus for a name the game, Spansh or a person uses: "Stratum", "Brain Trees",
/// `$Codex_Ent_Stratum_Genus_Name;`, `Bacterial` (Spansh's `genuses`). Case doesn't matter.
pub fn genus(name: &str) -> Option<&'static Genus> {
    let key = codex_key(name);
    genera().iter().find(|g| {
        g.name.eq_ignore_ascii_case(key)
            || key.strip_suffix(['s', 'S']).is_some_and(|k| g.name.eq_ignore_ascii_case(k))
            || g.codex.iter().any(|c| c.eq_ignore_ascii_case(key))
    })
}

/// `Stratum` from `$Codex_Ent_Stratum_Genus_Name;` (and `Brancae` from `$Codex_Ent_Brancae_Name;`);
/// anything else unchanged.
fn codex_key(name: &str) -> &str {
    let n = name.trim();
    let Some(n) = n.strip_prefix("$Codex_Ent_") else { return n };
    let n = n.trim_end_matches(';');
    let n = n.strip_suffix("_Name").unwrap_or(n);
    n.strip_suffix("_Genus").unwrap_or(n)
}

/// A species by its name as the game or Spansh writes it ("Stratum Tectonicas",
/// "Roseum Brain Tree"), with its genus.
pub fn species(name: &str) -> Option<(&'static Genus, &'static Species)> {
    let name = name.trim();
    genera().iter().find_map(|g| g.species.iter().find(|s| s.name.eq_ignore_ascii_case(name)).map(|s| (g, s)))
}

/// A species by its journal symbol (`$Codex_Ent_Stratum_07_Name;`, any case), with its genus.
pub fn species_by_symbol(symbol: &str) -> Option<(&'static Genus, &'static Species)> {
    let symbol = symbol.trim();
    genera().iter().find_map(|g| {
        g.species.iter().find(|s| s.symbol.as_deref().is_some_and(|x| x.eq_ignore_ascii_case(symbol))).map(|s| (g, s))
    })
}

/// What Vista Genomics pays for a sample, from the journal's `Species` and `Genus` symbols: the
/// species' base value, else for a genus whose species have no symbol here (the Horizons-era
/// anemones, brain trees, ...) the lowest value of its species. None if neither is known.
pub fn sample_value(species: &str, genus: &str) -> Option<i64> {
    if let Some((_, s)) = species_by_symbol(species) {
        return Some(s.value);
    }
    let g = self::genus(genus)?;
    g.species.iter().all(|s| s.symbol.is_none()).then(|| g.value_range().0)
}

impl Genus {
    /// The lowest and highest base value of its species.
    pub fn value_range(&self) -> (i64, i64) {
        let v = self.species.iter().map(|s| s.value);
        (v.clone().min().unwrap_or(0), v.max().unwrap_or(0))
    }
}

/// A journal `StarType` as the conditions name it: every white dwarf (`DA`, `DAB`, ...) is `D`,
/// a giant's suffix is dropped (`A_BlueWhiteSuperGiant` is `A`); `N`, `H`, `AeBe`, `TTS`, `K`,
/// ... stay as they are.
pub fn star_class(star_type: &str) -> String {
    let t = star_type.split('_').next().unwrap_or(star_type);
    if t.starts_with('D') {
        "D".into()
    } else {
        t.to_string()
    }
}
